(()=>{
  'use strict';
  const M=ToolStickerModel,Media=ToolStickerMedia,E=Site.esc;let H,busy=false,timer=null,epoch=0,paused=false,session=null,storageNote='',paintRevision=0;
  const current=()=>M.defaults(session||H.value());
  const button=(label,action,extra='',primary=false)=>`<button type="button" class="cm-button ${primary?'primary':'ghost'}" data-sticker="${action}" ${extra}>${label}</button>`;
  function write(patch,render=true){const next={...current(),...patch};try{H.write(next);session=null;storageNote='';}catch{session=next;storageNote='本机空间不足，当前只保留本次页面会话。仍可下载，保存成功才会进入个人成果。';}if(render)H.render();}
  function sources(){
    const entries=H.store.list().filter(item=>item.toolId==='oc-sheet'&&item.character&&item.images?.some(image=>image.role==='main')).map(item=>({key:'oc:'+item.id,scope:'oc',snapshotId:item.id,name:item.character.name||item.title,origin:'已保存 OC · v'+item.version,profile:item.character.profile,images:{main:item.images.find(image=>image.role==='portrait')?.src||item.images.find(image=>image.role==='main').src}}));
    let projects=[];try{projects=H.targets();}catch{}
    for(const entry of projects){const assets=entry.scope==='comic'?entry.project.assets:entry.context.e.videoFlow.workspace.assets;for(const asset of assets||[]){if(!['角色','人物'].includes(asset.kind))continue;const version=entry.scope==='comic'?asset.visualVersions?.find(part=>part.id===asset.adoptedVisualId):asset.candidates?.find(part=>part.id===asset.adoptedId);let main=version?.images?.portrait||version?.images?.main||version?.image||asset.reference;if(!main)continue;if(entry.scope==='comic'&&!/^(data:|https?:|blob:|\/|assets\/|comic-studio\/)/.test(main))main='comic-studio/'+main;entries.push({key:entry.key+':'+asset.id,scope:entry.scope,projectId:entry.project?.id||entry.context.p.id,episodeId:entry.context?.c.id,assetId:asset.id,versionId:version?.id,name:asset.name,origin:entry.label,profile:asset.characterProfile||asset.storyProfile||{},images:{main}});}}
    return entries.slice(0,60);
  }
  function sourceInput(value){return `<section class="stk-source"><div class="stk-row"><h2>① 用谁来做？</h2>${button('试用示例','sample')}</div><div class="stk-tabs" aria-label="角色来源">${[['upload','上传图片'],['existing','已有角色'],['describe','描述角色']].map(([key,label])=>button(label,'source-mode',`data-value="${key}" aria-pressed="${value.sourceMode===key}"`)).join('')}</div>${value.sourceMode==='upload'?'<label class="stk-upload">上传喜欢的角色<input id="stk-upload" type="file" accept="image/png,image/jpeg,image/webp"><small>PNG / JPG / WebP，6 MB 以内</small></label>':value.sourceMode==='existing'?`<label>选择已保存 OC 或作品角色<select id="stk-source"><option value="">请选择角色</option>${sources().map(source=>`<option value="${E(source.key)}" ${value.source?.key===source.key?'selected':''}>${E(source.origin+' / '+source.name)}</option>`).join('')}</select></label>`:'<label>你想创建什么角色？<textarea id="stk-character" rows="2" maxlength="500" placeholder="例如：戴圆框眼镜、总在加班的黑猫">'+E(value.characterDescription)+'</textarea></label><p class="stk-note">描述会保留为角色生成要求，AI 角色生成待接入；也可先试用示例。</p>'}${value.source&&value.sourceMode!=='describe'?`<div class="stk-identity"><img src="${E(value.source.images.main)}" alt="当前角色"><div><strong>${E(value.source.name)}</strong><small>${E(value.source.origin)}</small></div></div>`:''}</section>`;}
  function editor(value){const item=M.selected(value);return `<section class="stk-request"><h2>② 想表达什么？</h2><label>描述你的表情包<textarea id="stk-prompt" rows="3" maxlength="800" placeholder="例如：这个角色假笑着说好的，实际已经气炸了">${E(value.prompt)}</textarea></label><div class="stk-presets">${M.presets.map(preset=>button(preset.label,'preset',`data-id="${preset.id}"`)).join('')}</div><div class="stk-tabs" aria-label="表情包类型">${[['gif','动态 GIF'],['png','静态 PNG']].map(([format,label])=>button(label,'format',`data-value="${format}" aria-pressed="${value.format===format}"`)).join('')}</div>${button(value.items.length?'再做一张':'生成表情包','generate',!value.prompt.trim()?'disabled':'',true)}<p class="stk-note">先生成一张，再决定是否扩展整套。${value.sourceMode==='describe'?'':'本地预览保留人物原图，仅合成动作和配字。'}</p></section>${item?`<section class="stk-modify"><h2>修改选中的这一张</h2><p class="stk-note">${E(item.caption||'无配字')} · ${E(value.source.name)}</p>${value.chat.slice(-4).map(message=>`<p class="stk-chat ${message.role}">${E(message.text)}</p>`).join('')}<label>告诉 AI 怎么改<textarea id="stk-modify" rows="2" maxlength="500" placeholder="例如：动作慢一点，配字改成「好哒」"></textarea></label>${button('提交修改','revise')}<p class="stk-note">动作速度和配字可本地调整；改变表情、服饰等会记录为待接 AI 的改画要求。</p></section>`:''}`;}
  function output(value){const item=M.selected(value);return `<section class="ts-panel stk-output"><div class="stk-row"><div><h2>我的表情包</h2><p class="stk-note">${value.items.length?'同一个角色 · '+value.items.length+' 张':'先把一个想法变成一张表情包'}</p></div>${value.items.length?button('扩展为一套','expand',value.items.length>=6?'disabled':''):''}</div>${value.pending?`<div class="stk-pending"><strong>生成要求已整理</strong><p>${E(value.pending.characterDescription)}</p><p>${E(value.pending.prompt)}</p><small>AI 角色生成与表情改画待接入，当前画面保留原版本。可保留要求，或先试用示例。</small>${button('试用星奈示例','sample')}</div>`:''}${item?`<div class="stk-preview"><div class="stk-stage"><canvas width="320" height="320" data-sticker-main="${E(item.id)}" aria-label="${E(item.caption||'表情包')}预览"></canvas></div><div class="stk-preview-bar"><span>${item.format==='gif'?'循环 GIF':'静态 PNG'} · 320 × 320</span>${item.format==='gif'?button(paused?'▶ 播放':'Ⅱ 暂停','pause',`aria-pressed="${!paused}"`):''}${button('下载'+(item.format==='gif'?' GIF':' PNG'),'download','',true)}</div><div class="stk-caption"><label class="stk-caption-toggle"><input id="stk-caption-enabled" type="checkbox" ${item.captionEnabled?'checked':''}>添加配字</label><label>配字内容<input id="stk-caption" type="text" value="${E(item.caption)}" maxlength="60" placeholder="最多 30 个字" ${!item.captionEnabled?'disabled':''}></label><div class="stk-tabs" aria-label="配字样式">${[['outline','描边大字'],['bubble','对话气泡']].map(([style,label])=>button(label,'caption-style',`data-value="${style}" aria-pressed="${item.captionStyle===style}"`)).join('')}</div><small>文字独立叠加，改字不会重新生成人物。</small></div>${item.pending?`<div class="stk-pending"><strong>待 AI 改画</strong><p>${E(item.pending)}</p><small>当前画面保留原版本；下载和保存的仍是当前预览。</small></div>`:''}</div><div class="stk-card-grid">${value.items.map(part=>`<button type="button" data-sticker="select" data-id="${E(part.id)}" aria-pressed="${part.id===item.id}" class="stk-card"><canvas width="320" height="320" data-sticker-thumb="${E(part.id)}" aria-label="${E(part.caption||'无配字表情包')}"></canvas><span>${E(part.caption||'无配字')}</span><small>${part.format==='gif'?'GIF':'PNG'}${part.pending?' · 修改待生成':''}</small></button>`).join('')}</div><div class="stk-actions">${button('保存这一张','save')}${button('下载整套 ZIP','download-all',value.items.length<2?'disabled':'')}${button('移除这一张','remove')}</div><p class="stk-note">${E(item.origin)}。透明区域会保留；实际背景以原图为准，不自动抠图。</p>`:`<div class="stk-empty"><img src="assets/pngtuber/idle.png" alt="星奈示例角色"><h3>让你的角色替你说话</h3><p>一句「收到」、一个无语的摇头，<br>都可以变成能直接分享的表情包。</p>${button('试做一张「收到」','sample','',true)}<div class="stk-chips"><span>收到 ✓</span><span>拜托啦 ♡</span><span>啊啊啊！</span></div></div>`}</section>`;}
  function render(raw){const value=M.defaults({...raw,...session});return `<main class="ts-page stk-page"><header class="ts-heading"><div>${Site.link('← 创作工具','/app/tools','cm-text-link')}<h1>表情包创作</h1><p>用喜欢的角色，做一张想发出去的表情包。</p></div>${Site.link('我的工具成果','/app/tool-results','cm-button ghost')}</header><p class="stk-demo">本机 Demo · GIF 与配字可真实合成下载，AI 角色生成与表情改画待接入。</p><div class="stk-workbench"><section class="ts-panel stk-input">${sourceInput(value)}${editor(value)}<p id="stk-message" role="status"></p><p class="stk-note" role="status">${E(storageNote)}</p></section>${output(value)}</div></main>`;}
  function stop(){if(timer)clearInterval(timer);timer=null;paintRevision++;}
  async function hydrate(){stop();const value=current(),item=M.selected(value);if(!item||!document.querySelector('.stk-page'))return;const revision=paintRevision;try{const states=await Media.prepare(value.source);if(revision!==paintRevision||!document.querySelector('.stk-page'))return;for(const card of value.items){const canvas=document.querySelector(`[data-sticker-thumb="${card.id}"]`);if(canvas)Media.paint(canvas,states,card,0);}let frame=0;const paint=()=>{const canvas=document.querySelector('[data-sticker-main]');if(!canvas||canvas.dataset.stickerMain!==item.id){stop();return;}Media.paint(canvas,states,item,item.format==='gif'&&!paused?(frame++*item.speed/12)%1:0);};paint();if(item.format==='gif'&&!paused&&!document.hidden)timer=setInterval(paint,100);}catch(error){message(error);}}
  function message(error){const node=document.getElementById('stk-message');if(node)node.textContent=error.message||String(error);}
  function lock(value){busy=value;document.querySelector('.stk-page')?.setAttribute('aria-busy',String(value));for(const node of document.querySelectorAll('.stk-input,.stk-output'))node.inert=value;}
  async function select(source){const revision=epoch,previous=current();if(previous.items.length&&previous.source?.key!==source.key&&!window.confirm('更换角色会清空这套未保存的表情包；已保存成果保留。继续吗？')){H.render();return false;}await Media.prepare(source);if(revision!==epoch)return false;paused=false;write({source,sourceMode:source.scope==='sample'?'upload':source.scope==='upload'?'upload':'existing',items:[],selectedId:'',pending:null,chat:[]});return true;}
  async function outputs(value,all){const list=all?value.items:[M.selected(value)],results=[];const revision=epoch;for(const [index,item]of list.entries()){message('正在合成 '+(index+1)+' / '+list.length+'…');results.push(await Media.output(value.source,item));if(revision!==epoch)throw Error('已离开页面，合成已停止。');}return results;}
  async function downloadSnapshot(snapshot,emit){if(!emit&&window.ExportCenter){await ExportCenter.exportTool(snapshot);return true;}emit ||= Media.download;if(!snapshot.stickers)return false;const entries=snapshot.stickers.outputs.map((output,index)=>{const item=snapshot.stickers.items[index],extension=output.gif?'gif':'png';return{name:String(index+1).padStart(2,'0')+'-'+(item.caption||'表情包').replace(/[<>:"/\\|?*]/g,'_')+'.'+extension,data:Media.blob(output.gif||output.src)};});if(entries.length===1)await emit(entries[0].data,entries[0].name);else{const files=[];for(const entry of entries)files.push({name:entry.name,data:new Uint8Array(await entry.data.arrayBuffer())});files.push({name:'使用说明.txt',data:'Cimora 表情包合集\n'+snapshot.notice+'\n\n320 × 320，GIF 自动循环。聊天平台的表情上传限制各不相同，实际能否导入以目标平台为准。\n'});await emit(ToolPNGTuberZip.zip(files),'表情包合集.zip');}return true;}
  async function run(action,node){let value=current(),item=M.selected(value);
    if(action==='source-mode'){write({sourceMode:node.dataset.value});return;}
    if(action==='sample'){if(!await select({key:'sample:hoshina-sticker',scope:'sample',name:'星奈',origin:'预置原创角色',images:{main:'assets/pngtuber/idle.png'}}))return;write({prompt:M.presets[1].prompt,format:'gif'});write(M.generate(current(),Site.id));return;}
    if(action==='preset'){const preset=M.presets.find(part=>part.id===node.dataset.id);write({prompt:preset.prompt});return;}
    if(action==='generate'){write(M.generate(value,Site.id));return;}
    if(action==='expand'){write(M.expand(value,Site.id));return;}
    if(action==='format'){const format=node.dataset.value;write({format,items:value.items.map(part=>part.id===item?.id?{...part,format}:part)});return;}
    if(action==='select'){const selected=value.items.find(part=>part.id===node.dataset.id);write({selectedId:selected.id,format:selected.format});return;}
    if(action==='pause'){paused=!paused;H.render();return;}
    if(action==='caption-style'){write(M.caption(value,item.id,{captionStyle:node.dataset.value}));return;}
    if(action==='remove'){write({items:value.items.filter(part=>part.id!==item.id),selectedId:''});return;}
    if(action==='revise'){write(M.revise(value,item.id,document.getElementById('stk-modify').value));return;}
    if(['download','download-all','save'].includes(action)){const rendered=await outputs(value,action==='download-all'),snapshot=M.snapshot(value,rendered);if(action==='save'){H.store.save('sticker-maker',snapshot);Site.toast('已保存这张表情包，新旧成果独立保留。');}else await downloadSnapshot(snapshot);message('已完成，可继续修改或保存。');}
  }
  async function read(file){if(!file||!['image/png','image/jpeg','image/webp'].includes(file.type)||file.size>6*1048576)throw Error('请选择 6 MB 以内的 PNG、JPG 或 WebP 图片。');const src=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=()=>reject(Error('图片读取失败。'));reader.readAsDataURL(file);}),picture=new Image();picture.src=src;await picture.decode();if(picture.naturalWidth*picture.naturalHeight>12000000)throw Error('请选择 1200 万像素以内的角色图片。');const canvas=document.createElement('canvas'),scale=Math.min(1,600/Math.max(picture.width,picture.height));canvas.width=Math.round(picture.width*scale);canvas.height=Math.round(picture.height*scale);canvas.getContext('2d').drawImage(picture,0,0,canvas.width,canvas.height);const result=canvas.toDataURL('image/png');canvas.width=canvas.height=1;return{key:Site.id('sticker-source'),scope:'upload',name:file.name.replace(/\.[^.]+$/,''),origin:'上传角色 · 原图保留外观',images:{main:result}};}
  function savedHtml(snapshot){return `<p>${E(snapshot.notice)}</p><div class="stk-saved">${snapshot.stickers.outputs.map((output,index)=>`<figure><img src="${E(output.gif||output.src)}" alt="${E(snapshot.stickers.items[index].caption||'表情包')}"><figcaption>${E(snapshot.stickers.items[index].caption||'无配字')} · ${output.gif?'循环 GIF':'PNG'}</figcaption></figure>`).join('')}</div>`;}
  function init(helpers){H=helpers;window.addEventListener('hashchange',()=>{epoch++;stop();});document.addEventListener('visibilitychange',()=>{if(document.hidden)stop();else if(document.querySelector('.stk-page'))hydrate();});
    document.addEventListener('click',async event=>{const node=event.target.closest('[data-sticker]');if(!node)return;event.preventDefault();event.stopImmediatePropagation();if(busy)return;lock(true);try{await run(node.dataset.sticker,node);}catch(error){message(error);}finally{lock(false);}},true);
    document.addEventListener('input',event=>{const node=event.target;if(!['stk-prompt','stk-character','stk-caption','stk-modify'].includes(node.id))return;event.stopImmediatePropagation();if(busy||node.id==='stk-modify')return;try{const value=current();if(node.id==='stk-caption'){write(M.caption(value,M.selected(value).id,{caption:node.value}),false);const card=document.querySelector('.stk-card[aria-pressed=true] span');if(card)card.textContent=node.value||'无配字';hydrate();}else{write({[node.id==='stk-prompt'?'prompt':'characterDescription']:node.value},false);const generate=document.querySelector('[data-sticker=generate]');if(generate)generate.disabled=!current().prompt.trim();}message('');}catch(error){message(error);}},true);
    document.addEventListener('change',async event=>{const node=event.target;if(!['stk-upload','stk-source','stk-caption-enabled'].includes(node.id))return;event.stopImmediatePropagation();if(busy)return;lock(true);const revision=epoch;try{if(node.id==='stk-caption-enabled'){const value=current();write(M.caption(value,M.selected(value).id,{captionEnabled:node.checked}));return;}let source;if(node.id==='stk-source')source=sources().find(part=>part.key===node.value);else if(node.files?.[0])source=await read(node.files[0]);if(source&&revision===epoch)await select(source);}catch(error){message(error);}finally{lock(false);}},true);
  }
  window.ToolSticker={render,init,hydrate,stop,sources,download:downloadSnapshot,savedHtml};
})();
